import React, { useState } from "react";
import Papa from "papaparse";
import * as XLSX from "xlsx";
import { PieChart, Pie, Cell, Tooltip, Legend } from "recharts";

const COLORS = ["#8884d8", "#82ca9d", "#ffc658", "#ffb86c", "#5aa9fa", "#fa5a7d", "#16a085"];

function App() {
  const [data, setData] = useState([]);
  const [summary, setSummary] = useState({
    totalSales: 0,
    paymentMethods: {},
    shippingMethods: {},
    orderTypes: {},
    productOrders: {},
    cityOrders: {},
  });

  // رسم نسبة مئوية داخل الدائرة
  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }) => {
    const RADIAN = Math.PI / 180;
    const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
    const x = cx + radius * Math.cos(-midAngle * RADIAN);
    const y = cy + radius * Math.sin(-midAngle * RADIAN);
    return (
      <text x={x} y={y} fill="#111" fontWeight="bold" fontSize={20} textAnchor="middle" dominantBaseline="middle">
        {percent > 0 ? `${(percent * 100).toFixed(0)}%` : ""}
      </text>
    );
  };

  // رفع ملف جديد (CSV أو Excel)
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const fileName = file.name.toLowerCase();
    if (fileName.endsWith(".csv")) {
      Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: function (results) {
          setData(results.data);
          processData(results.data);
        },
      });
    } else if (fileName.endsWith(".xlsx") || fileName.endsWith(".xls")) {
      const reader = new FileReader();
      reader.onload = (evt) => {
        const data = new Uint8Array(evt.target.result);
        const workbook = XLSX.read(data, { type: "array" });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(firstSheet, { defval: "" });
        setData(jsonData);
        processData(jsonData);
      };
      reader.readAsArrayBuffer(file);
    } else {
      alert("الرجاء رفع ملف CSV أو Excel فقط!");
    }
  };

  function processData(rows) {
    let totalSales = 0;
    const paymentMethods = {};
    const shippingMethods = {};
    const orderTypes = { "قوقل كروم": 0, "ايفون": 0, "اندرويد": 0 };
    const productOrders = {};
    const cityOrders = {};

    // تجميع وتحليل البيانات
    rows.forEach(row => {
      // اجمالي المبيعات
      let total = parseFloat(row["teest"] || row["Grand Total (Base)"] || row["Grand Total (Purchased)"] || "0");
      if (!isNaN(total)) totalSales += total;

      // 1. Payment Method
      let pay = (row["Payment Method"] || "").toLowerCase();
      let payLabel = "أخرى";
      if (pay.includes("madfu")) payLabel = "مدفوع";
      else if (pay.includes("credit") || pay.includes("debit") || pay.includes("apple")) payLabel = "بطاقة ائتمانية";
      else if (pay.includes("tamara")) payLabel = "تمارا";
      else if (pay.includes("tabby")) payLabel = "تابي";
      paymentMethods[payLabel] = (paymentMethods[payLabel] || 0) + 1;

      // 2. Shipping Information
      let ship = (row["Shipping Information"] || "").toLowerCase();
      let shipLabel = "شحن عادي";
      if (ship.includes("سريع")) shipLabel = "شحن سريع +15 ريال - يشحن خلال 24 ساعة";
      else if (ship.includes("store pickup") || ship.includes("استلام من الفرع")) shipLabel = "استلام من الفرع";
      shippingMethods[shipLabel] = (shippingMethods[shipLabel] || 0) + 1;

      // 3. Order Type
      let type = (row["Order Type"] || "").toLowerCase();
      if (type.includes("web")) orderTypes["قوقل كروم"] += 1;
      else if (type.includes("ios")) orderTypes["ايفون"] += 1;
      else if (type.includes("android")) orderTypes["اندرويد"] += 1;

      // 4. Product Details (أكثر 10 منتجات)
      let details = row["Product Details"] || "";
      const items = details.split("|").filter((x) => x.trim().startsWith("Name:"));
      items.forEach((item) => {
        let name = item.replace("Name:", "").split("|")[0].trim();
        if (name) productOrders[name] = (productOrders[name] || 0) + 1;
      });

      // 5. Region (أكثر 5 مدن)
      let city = (row["Region"] || "").trim();
      if (city) cityOrders[city] = (cityOrders[city] || 0) + 1;
    });

    setSummary({
      totalSales,
      paymentMethods,
      shippingMethods,
      orderTypes,
      productOrders,
      cityOrders,
    });
  }

  // إعداد بيانات الرسوم والجدوال
  const paymentData = Object.entries(summary.paymentMethods).map(([name, value]) => ({ name, value }));
  const shippingTable = Object.entries(summary.shippingMethods)
    .sort((a, b) => b[1] - a[1])
    .map(([name, orders]) => ({ name, orders }));

  const orderTypeTable = Object.entries(summary.orderTypes)
    .map(([name, value]) => ({ name, value }));

  const topProducts = Object.entries(summary.productOrders)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10)
    .map(([name, orders]) => ({ name, orders }));

  const topCities = Object.entries(summary.cityOrders)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, orders]) => ({ name, orders }));

  return (
    <div style={{ fontFamily: "Tahoma, Arial, sans-serif", direction: "rtl", background: "#fafafa", minHeight: "100vh", padding: "32px" }}>
      <div style={{ position: "fixed", top: 18, right: 32, zIndex: 2001 }}>
        <input type="file" accept=".csv,.xlsx,.xls" onChange={handleFileUpload} style={{ marginRight: 16 }} />
      </div>

      <h1 style={{ textAlign: "center", marginBottom: 24 }}>لوحة تقارير الطلبات</h1>

      <div style={{ display: "flex", justifyContent: "center", marginBottom: 28 }}>
        <div style={{
          background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20,
          padding: "18px 32px", fontSize: 30, color: "#16a085", fontWeight: "bold", margin: "0 8px"
        }}>
          إجمالي المبيعات
          <div style={{ fontSize: 40 }}>{(summary.totalSales || 0).toLocaleString()} ريال</div>
        </div>
      </div>

      {/* رسم بياني لطريقة الدفع */}
      <div style={{ background: "white", borderRadius: 20, boxShadow: "0 2px 8px #eee", padding: 24, maxWidth: 410, margin: "30px auto" }}>
        <h3 style={{ textAlign: "center" }}>طريقة الدفع</h3>
        <PieChart width={350} height={260}>
          <Pie
            data={paymentData}
            cx="50%"
            cy="50%"
            outerRadius={90}
            fill="#8884d8"
            dataKey="value"
            label={renderCustomLabel}
            labelLine={false}
          >
            {paymentData.map((entry, index) => (
              <Cell key={`cell-pay-${index}`} fill={COLORS[index % COLORS.length]} />
            ))}
          </Pie>
          <Tooltip />
          <Legend />
        </PieChart>
      </div>

      {/* جدول طريقة الشحن */}
      <div style={{ background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: 24, maxWidth: 480, margin: "30px auto" }}>
        <h3 style={{ textAlign: "center" }}>طرق الشحن وعدد الطلبات</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
          <thead>
            <tr style={{ background: "#f1f1f1" }}>
              <th style={{ padding: 8 }}>وسيلة الشحن</th>
              <th style={{ padding: 8 }}>عدد الطلبات</th>
            </tr>
          </thead>
          <tbody>
            {shippingTable.map((ship, idx) => (
              <tr key={ship.name} style={{ borderBottom: "1px solid #f1f1f1" }}>
                <td>{ship.name}</td>
                <td>{ship.orders}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* جدول مصدر الطلب (Order Type) */}
      <div style={{ background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: 24, maxWidth: 480, margin: "30px auto" }}>
        <h3 style={{ textAlign: "center" }}>مصدر الطلبات</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
          <thead>
            <tr style={{ background: "#f1f1f1" }}>
              <th style={{ padding: 8 }}>المصدر</th>
              <th style={{ padding: 8 }}>عدد الطلبات</th>
            </tr>
          </thead>
          <tbody>
            {orderTypeTable.map((row, idx) => (
              <tr key={row.name}>
                <td>{row.name}</td>
                <td>{row.value}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* جدول أكثر 10 منتجات مبيعا */}
      <div style={{ background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: 24, maxWidth: 700, margin: "40px auto" }}>
        <h3 style={{ textAlign: "center" }}>أكثر 10 منتجات مبيعا</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
          <thead>
            <tr style={{ background: "#f1f1f1" }}>
              <th style={{ padding: 8 }}>الترتيب</th>
              <th style={{ padding: 8 }}>المنتج</th>
              <th style={{ padding: 8 }}>عدد الطلبات</th>
            </tr>
          </thead>
          <tbody>
            {topProducts.map((prod, idx) => (
              <tr key={prod.name}>
                <td>{idx + 1}</td>
                <td>{prod.name}</td>
                <td>{prod.orders}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* جدول أكثر المدن طلبًا */}
      <div style={{ background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: 24, maxWidth: 420, margin: "40px auto" }}>
        <h3 style={{ textAlign: "center" }}>أكثر 5 مدن طلبًا</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
          <thead>
            <tr style={{ background: "#f1f1f1" }}>
              <th style={{ padding: 8 }}>الترتيب</th>
              <th style={{ padding: 8 }}>المدينة</th>
              <th style={{ padding: 8 }}>عدد الطلبات</th>
            </tr>
          </thead>
          <tbody>
            {topCities.map((city, idx) => (
              <tr key={city.name}>
                <td>{idx + 1}</td>
                <td>{city.name}</td>
                <td>{city.orders}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

    </div>
  );
}

export default App;
